{% set na = ['unknown','unavailable','none',''] %}
{% set st = states('assist_satellite.ember_satellite_assist_satellite') %}
{% set pl = states('select.ember_satellite_assistant') %}
{% set chain = {
  'familiar-ember': ['Ember · local Qwen3.6-35B on familiar','vosk','piper','en_GB-cori-medium'],
  'claude-donkee': ['Claude Opus 4.7 · Bedrock','vosk','piper','en_US-hfc_female-medium'],
  'Chatgpt': ['ChatGPT','faster-whisper','piper','en_US-hfc_female-medium'],
  'Gemini-vosk-piper-donkee': ['Google Gemini','vosk','piper','en_US-hfc_female-medium'],
  'yurt-butler': ['Home Assistant','faster-whisper','piper','en_US-hfc_female-medium'],
  'Home Assistant': ['Home Assistant','—','HA Cloud','JennyNeural'],
  'preferred': ['Google Gemini · HA preferred','vosk','piper','en_US-hfc_female-medium']
} %}
{% set glyph = {'idle':'○','listening':'◉','processing':'◐','responding':'◆','responding_speaking':'◆'}.get(st,'·') %}
{% set p = chain.get(pl, ['—','—','—','—']) %}
# Ember
the hearth-spirit · **{{ glyph }} {{ st }}**

listening as **{{ pl }}** → {{ p[0] }}
{{ p[1] }} ⟶ {{ p[2] }} · *{{ p[3] }}*

hearth **{% set v = states('number.ember_satellite_speaker_volume') %}{{ (v | float | int) ~ '%' if v not in na else '—' }}** · amp **{{ states('switch.ember_satellite_speaker_amplifier') }}** · ear **{% set v = states('sensor.ember_satellite_mic_rms') %}{{ (v | float | round(1)) ~ ' dB' if v not in na else '—' }}** · coals **{% set v = states('sensor.ember_satellite_battery_voltage') %}{{ (v | float | round(2)) ~ ' V' if v not in na else '—' }}**

ha-card {
  --em-bed:#4A1002; --em-coal:#8E2206; --em-glow:#E05A08;
  --em-gold:#FFA81E; --em-tip:#FFE8B4; --em-alarm:#FF3C18;
  --em-ash:#3A322C; --em-dim:#6A5240;
}
@media (prefers-color-scheme: light) {
  ha-card {
    --em-bed:#8C2E0A; --em-coal:#B83A0C; --em-glow:#C2540C;
    --em-gold:#A84D06; --em-tip:#6B3A04; --em-alarm:#A81410;
    --em-ash:#D8CAB8; --em-dim:#8A7662;
  }
}

ha-card { border:none; box-shadow:none; padding:2px 6px 8px;
  background:radial-gradient(120% 160% at 8% 118%,
    color-mix(in srgb, var(--em-coal) 30%, transparent) 0%,
    color-mix(in srgb, var(--em-bed) 16%, transparent) 42%, transparent 74%); }

style.ha-markdown$:
h1 { font-family:'Georgia','IBM Plex Serif',serif; font-size:52px; line-height:.92;
  margin:0; letter-spacing:1px; color:var(--em-gold);
  text-shadow:0 0 26px color-mix(in srgb, var(--em-glow) 55%, transparent),
              0 0 6px color-mix(in srgb, var(--em-tip) 30%, transparent); }
p { margin:6px 0 0; font-size:13px; line-height:1.75;
  color:var(--secondary-text-color); letter-spacing:.3px; }
strong { color:var(--em-glow); font-weight:600; }
em { color:var(--em-tip); font-style:normal; letter-spacing:.6px; }

